suppressPackageStartupMessages({library(splines);library(jsonlite)})
a<-commandArgs(FALSE);a<-gsub('~+~',' ',sub('^--file=','',a[grep('^--file=',a)][1]),fixed=TRUE);ROOT<-dirname(dirname(normalizePath(a)));d<-read.csv(file.path(ROOT,'data/clinical_outcomes.csv'),colClasses=c(participant_id='character'));d$PPSD<-d$early_burden;d$mean_pain_0_24<-d$early_mean;d$late_high<-as.integer(d$observed_pain.36>=5 & d$observed_pain.48>=5);d$kl_factor<-factor(d$kl_factor)
vars<-c('PPSD','late_high','baseline_pain','baseline_expected_pain','mean_pain_0_24','kl_factor','jsn_medial','jsn_lateral','os_medial','os_lateral','age','bmi','female');d<-d[complete.cases(d[,vars]),];stopifnot(nrow(d)==512,!anyDuplicated(d$participant_id),all(abs(d$PPSD-(d$mean_pain_0_24-d$baseline_expected_pain))<1e-8))
cut<-quantile(d$PPSD,c(.1,.9));d$display_group<-ifelse(d$PPSD<=cut[1],'Lower decile',ifelse(d$PPSD>=cut[2],'Upper decile','Middle 80%'));write.csv(d,file.path(ROOT,'data/panel_definition_scatter.csv'),row.names=FALSE)
kn<-quantile(d$PPSD,c(1/3,2/3));bd<-range(d$PPSD);bas<-ns(d$PPSD,knots=kn,Boundary.knots=bd);d$s1<-bas[,1];d$s2<-bas[,2];d$s3<-bas[,3]
covs<-c('baseline_pain','kl_factor','jsn_medial','jsn_lateral','os_medial','os_lateral','age','bmi','female');f<-reformulate(c('s1','s2','s3',covs),'late_high');full<-glm(f,d,family=binomial());null<-glm(reformulate(covs,'late_high'),d,family=binomial());linear<-glm(reformulate(c('PPSD',covs),'late_high'),d,family=binomial());stopifnot(full$converged)
grid<-seq(quantile(d$PPSD,.02),quantile(d$PPSD,.98),length.out=61);Bgrid<-predict(bas,grid);Xlist<-lapply(seq_along(grid),function(i){nd<-d;nd$s1<-Bgrid[i,1];nd$s2<-Bgrid[i,2];nd$s3<-Bgrid[i,3];model.matrix(delete.response(terms(full)),nd)})
curve<-function(beta)vapply(Xlist,function(X)mean(plogis(X%*%beta)),numeric(1));point<-curve(coef(full));boot<-matrix(NA_real_,1000,length(grid));set.seed(2026110803);ok<-logical(1000)
for(i in 1:1000){ix<-sample.int(nrow(d),replace=TRUE);fit<-tryCatch(suppressWarnings(glm(f,d[ix,],family=binomial(),control=glm.control(maxit=100))),error=function(e)NULL);if(!is.null(fit)&&fit$converged&&all(is.finite(coef(fit)))){boot[i,]<-curve(coef(fit));ok[i]<-TRUE};if(i%%250==0){cat('Bootstrap',i,'valid',sum(ok),'\n');flush.console()}}
stopifnot(sum(ok)>=950);ci<-apply(boot[ok,,drop=FALSE],2,quantile,c(.025,.975));res<-data.frame(PPSD=grid,probability=point,lower=ci[1,],upper=ci[2,]);write.csv(res,file.path(ROOT,'data/panel_dose_response.csv'),row.names=FALSE)
lrt<-function(small,big){v<-anova(small,big,test='LRT');as.numeric(v$`Pr(>Chi)`[2])};overall<-lrt(null,full);nonlin<-lrt(linear,full)
notes<-list(n=nrow(d),events=sum(d$late_high),P10=unname(cut[1]),P90=unname(cut[2]),n_lower=sum(d$display_group=='Lower decile'),n_upper=sum(d$display_group=='Upper decile'),overall_p=overall,nonlinearity_p=nonlin,bootstrap=1000,bootstrap_valid=sum(ok),knots=unname(kn),boundaries=bd,formula=deparse(f),outcome='Actual WOMAC pain >=5 at both months 36 and 48',method='Natural cubic spline, 3 df; fixed knot positions and fixed empirical covariate distribution; participant bootstrap refits',interpretation='Selected-sample standardized probability, not population risk or a causal dose response',scatter_note='PPSD is defined from mean pain minus expected pain; highlighted separation is descriptive and partly by construction')
write_json(notes,file.path(ROOT,'reports/new_analysis.json'),pretty=TRUE,auto_unbox=TRUE,digits=12);write.csv(data.frame(term=names(coef(full)),coefficient=coef(full)),file.path(ROOT,'data/dose_model_coefficients.csv'),row.names=FALSE);saveRDS(full,file.path(ROOT,'data/dose_model.rds'));writeLines(capture.output(summary(full)),file.path(ROOT,'reports/dose_model_summary.txt'));cat(toJSON(notes,auto_unbox=TRUE,pretty=TRUE))
